cypher:
MATCH (h:Host {name: 'minio'})-[:RUNS]->(c1:Container), (h)-[:RUNS]->(c2:Container)
WHERE c1 <> c2
RETURN c2;

MATCH (container:Container {name: 'grafana'})
CALL {
  MATCH (dep:Container)-[:DEPENDS_ON]->()
  RETURN dep.name AS dependency_name
}
RETURN dependency_name

MATCH (n:Container {name: 'nextcloud'})
CALL {
  MATCH (c:Container)
  WHERE (n)-[:DEPENDS_ON]->(c)
  RETURN c.image AS image, c.name AS name
}

MATCH (h:Host {name: 'coolify'})-[:RUNS]->(c1:Container), c1-[:DEPENDS_ON]->(c2)
WHERE c1 <> c2
RETURN c2.name, c2.status;

MATCH (host:Host {name: 'prometheus'})
MATCH (container:Container)-[:RUNS]->(host)<-[RUNS]-(other-container:Container)
RETURN other-container.name, other-container.image, other-container.status;

MATCH (h:Host {name: 'minio'})-[:RUNS]->(c1:Container)-[:DEPENDS_ON]->(c2:Container)
WHERE c1 <> c2
RETURN c2.name AS ContainerName;

MATCH (h:Host {name: 'pve-node1'})-[:RUNS]->(c:Container)
RETURN c.name, c.image
ORDER BY c.name ASC;
